edits.replace:
 * Builds the comparator for orderBy. Null and undefined values sort last, or
 * first with nullsFirst, in both directions. Other values sort ascending, or
 * descending with descending.
 *
 * @param {boolean} [descending]
 * @param {boolean} [nullsFirst]
 * @returns {(a: any, b: any) => number}
 */
function comparator(descending, nullsFirst) {
  const direction = descending ? -1 : 1
  const nullOrder = nullsFirst ? -1 : 1
  return (a, b) => {
    const aMissing = a === null || a === undefined
    const bMissing = b === null || b === undefined
    if (aMissing || bMissing) return nullOrder * (Number(aMissing) - Number(bMissing))
    if (a < b) return -direction
    if (a > b) return direction
    return 0
  }
}
